// --- Signed request helper (identical scheme to Convex convex/lib/crypto.ts) ---
// signature = "sha256=" + hex(HMAC_SHA256(LENDLOOP_AUTOMATION_SECRET, `${timestamp}.${nonce}.${body}`))
// `body` is the exact string the next HTTP Request node sends as its raw body.
const crypto = require('crypto');
function signedRequest(path, payload) {
  const secret = $env.LENDLOOP_AUTOMATION_SECRET;
  const base = String($env.LENDLOOP_CONVEX_SITE_URL || '').trim().replace(/\/+$/, '');
  if (typeof secret !== 'string' || secret.length < 32) throw new Error('LENDLOOP_AUTOMATION_SECRET is not configured');
  if (!/^https?:\/\/\S+$/.test(base)) throw new Error('LENDLOOP_CONVEX_SITE_URL is not configured');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${nonce}.${body}`).digest('hex');
  return { url: base + path, body, timestamp, nonce, signature };
}
// -----------------------------------------------------------------------------
// --- Redaction helper: never forward emails, signatures, secrets or OTP-like numbers ---
function redact(text, max = 1000) {
  let s = String(text ?? '');
  for (const name of ['LENDLOOP_AUTOMATION_SECRET', 'LENDLOOP_N8N_WEBHOOK_SECRET']) {
    const v = $env[name];
    if (typeof v === 'string' && v.length >= 16) s = s.split(v).join('[redacted]');
  }
  return s
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]')
    .replace(/\b(bearer|basic)\s+[A-Za-z0-9._~+/=-]+/gi, '$1 [redacted]')
    .replace(/sha256=[A-Fa-f0-9]+/g, 'sha256=[redacted]')
    .replace(/\b(password|passwd|pass|secret|token|api[_-]?key|authorization)(["']?\s*[:=]\s*["']?)[^\s"',;&}]+/gi, '$1$2[redacted]')
    .replace(/\b\d{6,}\b/g, '[number]')
    .slice(0, max);
}
// -----------------------------------------------------------------------------
// Built only from Error Trigger metadata (workflow, execution id, last node, error message).
// The failing execution's input payload is never read or forwarded.
const data = $input.first().json;
const execution = data.execution || {};
const trigger = data.trigger || {};
const workflow = data.workflow || {};
const err = execution.error || trigger.error || {};

// n8n may replace a message with a generic text (e.g. "The service refused the connection")
// and keep the original in `messages`, so combine message, description and messages.
const parts = [];
const addPart = (s) => { if (typeof s === 'string' && s.trim() && !parts.some((p) => p.includes(s))) parts.push(s.trim()); };
addPart(typeof err === 'string' ? err : err.message);
addPart(err.description);
if (Array.isArray(err.messages)) err.messages.forEach(addPart);
const message = parts.join(' - ') || 'Unknown workflow error';
// LendLoop workflows put the event id in their own error messages ("... failed for evt_...").
const relatedEvent = message.match(/\bevt_[A-Za-z0-9]{1,96}\b/);
const failedNode = execution.lastNodeExecuted || err.node?.name;

const report = {
  workflowName: String(workflow.name || workflow.id || 'unknown workflow').slice(0, 100),
  errorMessage: redact(message, 1000) || 'Unknown workflow error',
  occurredAt: Date.now(),
};
if (execution.id !== undefined && execution.id !== null) report.executionId = String(execution.id).slice(0, 100);
if (failedNode) report.failedNode = String(failedNode).slice(0, 100);
if (relatedEvent) report.relatedEventId = relatedEvent[0];

return [{ json: { report, request: signedRequest('/automation/errors', report) } }];
